import logging
import os
import re

from ..command import CommandBuilder

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class WorkingSetManager:
    SCRIPT_PATH = 'wsetmgrcli.sh'

    def __init__(self, ssh_syswas_node):
        self.ssh_node = ssh_syswas_node

    def create(self, ws_name, dist_names, timeout=120):
        """
        Create a working set with defined managed objects using `import` command.

        :param str ws_name: Name of the working set to be created
        :param str|list(str) dist_names: Distinguished name(s) of managed object(s)
            to be attached to the working set
        :param int timeout: Timeout for executing command
        :return: Command's output
        :rtype: str
        """
        if isinstance(dist_names, list):
            file_content = '\n'.join(dist_names)
        else:
            file_content = dist_names
        remote_file = f'/tmp/{ws_name}.txt'
        flags = ['-import']
        options = {
            '-name': ws_name,
            '-file': remote_file,
        }
        command = CommandBuilder(executable=self.SCRIPT_PATH, flags=flags, options=options).text
        with self.ssh_node as ssh:
            try:
                ssh.put_file_content(file_content, remote_file)
                logger.info(f'Executing command: {command}')
                return ssh.execute_command(command=command, timeout=timeout).stdout
            finally:
                ssh.execute_command(f'rm -f "{remote_file}"')

    def delete(self, ws_names, ignore_errors=False, timeout=120):
        """
        Delete the defined working sets.

        :param str|list(str) ws_names: Name(s) of the working set(s) to be deleted
        :param bool ignore_errors: If True, shows warnings instead of raising errors when command fails.
        :param int timeout: Timeout for executing command
        :return: Names of the deleted working sets
        :rtype: list
        """
        flags = ['-delete']
        if isinstance(ws_names, str):
            ws_names = [ws_names]
        command = CommandBuilder(executable=self.SCRIPT_PATH, flags=flags, arguments=ws_names).text
        with self.ssh_node as ssh:
            logger.info(f'Executing command: {command}')
            stdout = ssh.execute_command(command=command,
                                         ignore_stderr=ignore_errors,
                                         ignore_rc=ignore_errors,
                                         timeout=timeout).stdout
            logger.debug(stdout)
        return self._convert_delete_stdout(stdout)

    def import_from_files(self, files, timeout=120):
        """
        Import working sets from files.

        :param str|list(str) files: Path to file(s) containing DNs to be attached to a working set.
            Each DN must be on a separate line. The working set name will be the name of the file.
            Paths to local and remote (stored on NetAct) files are supported.
            The local one will be used if file with the same name exists on NetAct under `/tmp/` directory
        :param int timeout: Timeout for executing command
        :return: Command's output
        :rtype: str
        """
        flags = [
            '-import',
            '-files'
        ]
        if isinstance(files, str):
            files = [files]
        local_files = {file for file in files if os.path.exists(file)}
        files_to_put = [f'/tmp/{os.path.basename(file)}' for file in local_files]
        remote_files = set(files_to_put)
        with self.ssh_node as ssh:
            try:
                remote_files.update({file for file in files if ssh.file_exists(file)})
                if not remote_files:
                    exc_msg = (f"None of the specified files exist, "
                               f"either locally or remotely: {', '.join(files)}")
                    raise ValueError(exc_msg)
                for lf, rf in zip(local_files, files_to_put):
                    ssh.put_file(lf, rf)
                command = CommandBuilder(executable=self.SCRIPT_PATH,
                                         flags=flags,
                                         arguments=sorted(remote_files)).text
                logger.info(f'Executing command: {command}')
                return ssh.execute_command(command=command, timeout=timeout).stdout
            finally:
                for rf in files_to_put:
                    ssh.execute_command(f'rm -f "{rf}"')

    def list(self, timeout=120):
        """
        List all working sets.

        Example output::

            [
                {
                    'created_by': 'omc',
                    'last_modified': '2024-04-04',
                    'last_modified_by': 'omc',
                    'name': 'WS-1',
                    'state': '',
                    'type': 'DN List'
                 }
            ]

        :param int timeout: Timeout for executing command
        :return: Names of existing working sets
        :rtype: list
        """
        flags = ['-list']
        command = CommandBuilder(executable=self.SCRIPT_PATH, flags=flags).text
        with self.ssh_node as ssh:
            logger.info(f'Executing command: {command}')
            stdout = ssh.execute_command(command=command, timeout=timeout).stdout
            logger.debug(stdout)
        return self._convert_list_stdout(stdout)

    def resolve(self, ws_name, timeout=120):
        """
        Resolve managed objects of the working set.

        :param str ws_name: Name of the working set to be resolved
        :param int timeout: Timeout for executing command
        :return: Distinguished name(s) of managed object(s) attached to the working set
        :rtype: list
        """
        options = {'-resolve': ws_name}
        command = CommandBuilder(executable=self.SCRIPT_PATH, options=options).text
        with self.ssh_node as ssh:
            logger.info(f'Executing command: {command}')
            stdout = ssh.execute_command(command=command, timeout=timeout).stdout
            logger.debug(stdout)
        return self._convert_resolve_stdout(stdout)

    @staticmethod
    def _convert_delete_stdout(stdout):
        msg = "working sets have been deleted successfully"
        if msg in stdout.lower():
            return [line for line in stdout.splitlines() if msg not in line]
        return []

    def _convert_list_stdout(self, stdout):
        header_pattern = re.compile(r'(Name\s+)'
                                    r'(Type\s+)'
                                    r'(Last modified\s+)'
                                    r'(Last modified by\s+)'
                                    r'(Created by\s+)'
                                    r'State')
        lines = stdout.splitlines()
        header_match = header_pattern.search(lines[0])
        if not header_match:
            return []
        columns_length = [len(e) for e in header_match.groups()]
        columns_pattern = re.compile(rf'(.{{{columns_length[0]}}})'
                                     rf'(.{{{columns_length[1]}}})'
                                     rf'(.{{{columns_length[2]}}})'
                                     rf'(.{{{columns_length[3]}}})'
                                     rf'(.{{,{columns_length[4]}}})'
                                     rf'(.*)')
        rows = columns_pattern.findall(stdout)
        header = self._convert_list_header_items(rows.pop(0))
        return [dict(zip(header, self._strip_list_row_items(row))) for row in rows]

    @staticmethod
    def _strip_list_row_items(row):
        return [e.strip() for e in row]

    @staticmethod
    def _convert_list_header_items(header):
        return [e.strip().lower().replace(' ', '_') for e in header]

    @staticmethod
    def _convert_resolve_stdout(stdout):
        msg = "no managed objects for working set"
        if msg in stdout.lower():
            return []
        return stdout.splitlines()
